<?php
$fmtKg = static fn(int $value): string => number_format($value, 0, ',', ' ');
$fmtDate = static fn(string $value): string => $value !== '' ? ui_date($value) : '—';
$warehouseFilter = (int)($_GET['warehouse'] ?? 0);
$showAllWarehouses = (string)($_GET['show_all'] ?? '') === '1';
$directionFilter = in_array((string)($_GET['operation'] ?? ''), ['in', 'out'], true) ? (string)$_GET['operation'] : '';
$search = trim((string)($_GET['q'] ?? ''));
$canCorrect = (string)($_SESSION['role_code'] ?? '') === 'company_owner';
$canExclude = $canCorrect && ($data['exceptions_available'] ?? true);
$upperWarehouse = static fn(string $name): string => mb_strtoupper($name, 'UTF-8');
$upperWarehouseInMessage = static function (string $message) use ($data, $upperWarehouse): string {
    foreach ($data['warehouses'] as $name) {
        $prefix = $name.' / ';
        if (str_starts_with($message, $prefix)) {
            return $upperWarehouse($name).substr($message, strlen($name));
        }
    }
    return $message;
};
$hasStock = static function (int $warehouseId) use ($data): bool {
    $stock = $data['current'][$warehouseId] ?? [];
    return (int)($stock['request_count'] ?? 0) > 0 || (int)($stock['weight_kg'] ?? 0) !== 0;
};
$visible = $data['groups'];
$visibleCount = array_sum(array_map('count', $visible));
